        String s = sc.next();
        int n = s.length();

        if (n < 2) {
            System.out.println((s.equals("0") || s.equals("_") || s.equals("X")) ? 1 : 0);
            return;
        }

        if (n == 2) {
            int total = 0;
            for (int i = 10; i <= 95; i += 5) {
                if (i % 25 != 0) continue;
                String strVal = Integer.toString(i);
                char c1 = s.charAt(0);
                char c2 = s.charAt(1);
                if (Character.isDigit(c1)) {
                    if (Character.isDigit(c2)) {
                        if (s.equals(strVal)) total++;
                    } else {
                        if (c1 == strVal.charAt(0)) total++;
                    }
                } else if (c1 == '_') {
                    if (Character.isDigit(c2)) {
                        if (c2 == strVal.charAt(1)) total++;
                    } else {
                        total++;
                    }
                } else {
                    if (Character.isDigit(c2)) {
                        if (c2 == strVal.charAt(1)) total++;
                    } else if (c2 == '_') {
                        total++;
                    }
                }
            }
            System.out.println(total);
            return;
        }

        int startNum = (int) Math.pow(10, n - 1);
        int endNum = (int) Math.pow(10, n);
        int count = 0;

        for (int num = startNum; num < endNum; num += 25) {
            String numStr = Integer.toString(num);
            boolean matchFlag = true;
            Set<Character> diffSet = new HashSet<>();
            for (int j = 0; j < n; j++) {
                char patternChar = s.charAt(j);
                char digitChar = numStr.charAt(j);
                if (patternChar == '_') continue;
                if (patternChar == 'X') {
                    diffSet.add(digitChar);
                } else if (patternChar != digitChar) {
                    matchFlag = false;
                    break;
                }
            }
            if (matchFlag && diffSet.size() < 2) {
                count++;
            }
        }
        System.out.println(count);
        sc.close();
    }
}
